import json, re
from pathlib import Path
manifest_path = Path('/mnt/data/LSF/baseline_results/court/agentic_codex_qa_gpt54_all/first_10_queries/q07/logs/q07.manifest.json')
output_path = Path('/mnt/data/LSF/baseline_results/court/agentic_codex_qa_gpt54_all/first_10_queries/q07/logs/q07.answers.json')

with manifest_path.open() as f:
    manifest = json.load(f)
question = manifest['questions'][0]

MONTHS = 'January|February|March|April|May|June|July|August|September|October|November|December'
month_line_re = re.compile(rf'"'^(?:{MONTHS})'"\\s+\\d{{1,2}},\\s+\\d{{4}}"'$'"')
filed_re = re.compile(rf'\\bFiled\\s+(({MONTHS})\\s+\\d{{1,2}},\\s+\\d{{4}})\\b')
stamp_re = re.compile(r'\\bFILED\\b[\\s\\S]{0,120}?\\b(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)\\s+(\\d{1,2})\\s+(\\d{4})\\b')
month_map = {
    'JAN': 'January', 'FEB': 'February', 'MAR': 'March', 'APR': 'April', 'MAY': 'May', 'JUN': 'June',
    'JUL': 'July', 'AUG': 'August', 'SEP': 'September', 'OCT': 'October', 'NOV': 'November', 'DEC': 'December'
}

answers = {}
not_found = []

for doc in manifest['documents']:
    text = Path(doc['doc_path']).read_text(encoding='utf-8', errors='ignore')
    answer = None

    m = filed_re.search(text)
    if m:
        answer = m.group(1)
    else:
        m = stamp_re.search(text)
        if m:
            answer = f\"{month_map[m.group(1)]} {int(m.group(2))}, {m.group(3)}\"
        else:
            lines = [ln.strip() for ln in text.splitlines()[:120]]
            for i, line in enumerate(lines):
                if month_line_re.fullmatch(line):
                    prev = lines[i - 1] if i > 0 else ''
                    nxt = lines[i + 1] if i + 1 < len(lines) else ''
                    blocked = any(token in prev for token in ['Filed ', 'Amended ', 'Argued and Submitted', 'Resubmitted', 'Submitted '])
                    blocked = blocked or any(token in line for token in ['Filed ', 'Amended ', 'Argued and Submitted', 'Resubmitted', 'Submitted '])
                    # Accept standalone header date lines like \"September 8, 2025\".
                    if not blocked and 'Before:' in nxt:
                        answer = line
                        break
            if answer is None:
                # Last-resort standalone date in the top header region.
                for i, line in enumerate(lines):
                    if month_line_re.fullmatch(line):
                        prev = lines[i - 1] if i > 0 else ''
                        if not any(token in prev for token in ['Amended ', 'Argued and Submitted', 'Resubmitted', 'Submitted ']):
                            answer = line
                            break

    if answer is None:
        answer = 'NOT_FOUND'
        not_found.append(doc['doc_name'])

    answers[doc['doc_name']] = {question: answer}

output = {'answers': answers}
output_path.write_text(json.dumps(output, indent=2, ensure_ascii=True) + '\\n', encoding='utf-8')
print(f'wrote {output_path}')
print(f'not_found_count {len(not_found)}')
for name in not_found:
    print(name)
PY"

